void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    float a = iResolution.x*(sin(iTime)+ sin(fragCoord.x));
    float b = iResolution.y*(cos(iTime)+ cos(fragCoord.y));

    a=a*0.02;
    b=b*0.02;
    vec3 col = vec3(a,b/2.0,tan(a*b));
    col = col + ((mod(fragCoord.x,500.0 * sin(iTime))/100.0));
    // Output to screen
    fragColor = vec4(col,1.0);
}
